#include <iostream>

int main() {
    int a = 0;
    int b = 0;
    int c = 0;

    if (std::cin >> a >> b >> c) {
        // Correct lvalue assignment: sum on left, rvalue expression on right
        int sum = a + b + c;
        int product = a * b * c;

        // Proper relational operator '>='
        if (product >= sum) {
            std::cout << "Product " << product << " >= Sum " << sum << "\n";
        }

        // Explicit equality comparison '==' instead of assignment '='
        if (a == b) {
            std::cout << "a equals b\n";
        } else {
            std::cout << "a does not equal b\n";
        }
    }
    return 0;
}

#include <iostream>

int main() {
    int val = 0;
    char ch = ' ';

    if (std::cin >> val >> ch) {
        // Operator precedence demonstration
        // 7 + (3 * 6 / 2) - 1 => 7 + 9 - 1 = 15
        int exprResult = 7 + 3 * 6 / 2 - 1;
        std::cout << "Expr: " << exprResult << "\n";

        // Parity test via modulo operator %
        if (val % 2 == 0) {
            std::cout << val << " is even\n";
        } else {
            std::cout << val << " is odd\n";
        }

        // Integer representation of character (ASCII code point)
        int charCode = static_cast<int>(ch);
        std::cout << "Char: " << ch << " Code: " << charCode << "\n";
    }
    return 0;
}
